    "sourceUrl": "https://agenciabrasil.ebc.com.br",
    "articleUrl": "https://agenciabrasil.ebc.com.br/meio-ambiente/noticia/2026-11/chuvas-no-rs-afetam-mais-de-25-mil-pessoas-em-42-cidades",
    "publishedAt": "22/11/2026 às 12:35",
    "category": "Política",
    "ingestedAt": "22/11/2026 às 13:55",
    "imageUrl": "https://imagens.ebc.com.br/Ed0rtuRHuGeh74s5pLlu5XWwgGU=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2026/11/20/temporalrs.jpg?itok=yZBQlUQh",
